package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.jsonFormatVisitors.*;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for DateTimeSerializerBase._serializeAsString
 */
public class DateTimeSerializerBase__serializeAsString_TriageGen1Test {

    private JsonGenerator g;
    private SerializerProvider provider;
    private Date testDate;

    // Concrete implementation of the abstract class for testing
    private static class TestDateTimeSerializer extends DateTimeSerializerBase<Object> {
        protected TestDateTimeSerializer(Class<Object> type, Boolean useTimestamp, DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
        }

        @Override
        public void serialize(Object value, JsonGenerator gen, SerializerProvider serializers) throws IOException {
            _serializeAsString((Date) value, gen, serializers);
        }

        @Override
        protected long _timestamp(Object value) {
            return 0L;
        }

        // Accessor for protected method if needed, but we test via serialize or reflection
        // Since it is protected, we can call it directly in this subclass
        public void testSerialize(Date value, JsonGenerator g, SerializerProvider provider) throws IOException {
            _serializeAsString(value, g, provider);
        }
    }

    @Before
    public void setUp() {
        g = mock(JsonGenerator.class);
        provider = mock(SerializerProvider.class);
        testDate = new Date(1234567890L); // Fixed date for consistency
    }

    @Test
    public void testSerializeWithNullCustomFormat() throws IOException {
        // Branch: _customFormat == null
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Object.class, false, null);

        serializer.testSerialize(testDate, g, provider);

        verify(provider).defaultSerializeDateValue(testDate, g);
        verify(g, never()).writeString(anyString());
    }

    @Test
    public void testSerializeWithCustomFormatAndReuse() throws IOException {
        // Branch: _customFormat != null
        // This covers the logic where f = _reusedCustomFormat.getAndSet(null) is null, 
        // then f = clone(), then g.writeString, then compareAndSet
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Object.class, false, sdf);

        serializer.testSerialize(testDate, g, provider);

        String expectedDate = sdf.format(testDate);
        verify(g).writeString(expectedDate);
        verify(provider, never()).defaultSerializeDateValue(any(), any());
    }

    @Test
    public void testSerializeWithReusedFormat() throws IOException {
        // Branch: f = _reusedCustomFormat.getAndSet(null) is NOT null
        // This tests the optimization path where the formatter is reused from the ThreadLocal-like holder
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Object.class, false, sdf);

        // First call to populate the reused format
        serializer.testSerialize(testDate, g, provider);
        reset(g);

        // Second call - the internal _reusedCustomFormat should now contain the formatter from the first call
        serializer.testSerialize(testDate, g, provider);

        String expectedDate = sdf.format(testDate);
        verify(g).writeString(expectedDate);
    }

    @Test
    public void testSerializeThrowsIOException() throws IOException {
        // Test error propagation
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Object.class, false, sdf);

        doThrow(new IOException("Simulated error")).when(g).writeString(anyString());

        try {
            serializer.testSerialize(testDate, g, provider);
        } catch (IOException e) {
            assert(e.getMessage().equals("Simulated error"));
        }
    }
}
